27	impl<Sel> PrefillRouter<Sel>
28	where
29	    Sel: WorkerSelector<ModelRuntimeConfig> + Send + 'static,
30	{
31	    pub(super) async fn consume_prefill_stream(
32	        mut prefill_response: ManyOut<Annotated<LLMEngineOutput>>,
33	        tracker: Option<Arc<RequestTracker>>,
34	        task_guard: Option<dynamo_runtime::engine::EngineContextGuard>,
35	    ) -> Result<PrefillCompletion, PrefillError> {
36	        let Some(first_output) = prefill_response.next().await else {
37	            return Err(PrefillError::PrefillError(
38	                "Prefill router returned no output (stream ended)".to_string(),
39	                None,
40	            ));
41	        };
42	
43	        if let Some(error) = first_output.err() {
44	            return Err(PrefillError::PrefillError(
45	                "Prefill router returned error in output".to_string(),
46	                Some(Box::new(error)),
47	            ));
48	        }
49	
50	        if let Some(ref tracker) = tracker {
51	            tracker.record_prefill_complete();
52	        }
53	
54	        let mut prompt_tokens_details = first_output
55	            .data
56	            .as_ref()
57	            .and_then(|output| output.completion_usage.as_ref())
58	            .and_then(|usage| usage.prompt_tokens_details.clone());
59	
60	        // For SGLang, check if the first output is a bootstrap message.
61	        let is_bootstrap = first_output
62	            .data
63	            .as_ref()
64	            .and_then(|o| o.disaggregated_params.as_ref())
65	            .and_then(|p| p.as_object())
66	            .is_some_and(|obj| {
67	                obj.contains_key("bootstrap_host")
68	                    && obj.contains_key("bootstrap_port")
69	                    && obj.contains_key("bootstrap_room")
70	            });
71	
72	        if !is_bootstrap {
73	            while let Some(next) = prefill_response.next().await {
74	                if let Some(error) = next.err() {
75	                    return Err(PrefillError::PrefillError(
76	                        "Prefill router returned error in output stream".to_string(),
77	                        Some(Box::new(error)),
78	                    ));
79	                }
80	                if let Some(output) = next.data.as_ref()
81	                    && prompt_tokens_details.is_none()
82	                {
83	                    prompt_tokens_details = output
84	                        .completion_usage
85	                        .as_ref()
86	                        .and_then(|usage| usage.prompt_tokens_details.clone());
87	                }
88	            }
89	        } else {
90	            tokio::spawn(async move {
91	                let _task_guard = task_guard;
92	                while prefill_response.next().await.is_some() {}
93	            });
94	        }
95	
96	        // A CTX request that reaches EOS/stop during its one-token prefill step
97	        // is already complete and does not establish a KV-cache handoff. The
98	        // prefill protocol carries this classification on the first output's
99	        // data; a data-less first output is rejected below. A missing finish
100	        // reason is equivalent to TRT-LLM's "not_finished", while Length still
101	        // requires the normal GEN handoff.
102	        let is_terminal = first_output
103	            .data
104	            .as_ref()
105	            .and_then(|output| output.finish_reason.as_ref())
106	            .is_some_and(|reason| !matches!(reason, FinishReason::Length));
107	        if is_terminal {
108	            return Ok(PrefillCompletion::Terminal {
109	                output: Box::new(first_output),
110	            });
111	        }
112	
113	        let Some(output) = &first_output.data else {
114	            return Err(PrefillError::NoDisaggregatedParams(
115	                "Prefill router output has no data field".to_string(),
116	            ));
117	        };
118	        let Some(disaggregated_params) = output.disaggregated_params.clone() else {
119	            return Err(PrefillError::NoDisaggregatedParams(
120	                "Prefill router output missing disaggregated_params".to_string(),
121	            ));
122	        };
123	        // TRT-LLM serializes ctx_request_id as null for a terminal context
124	        // response. Terminal responses returned above do not need a handoff;
125	        // any non-terminal response that explicitly carries a null ID cannot
126	        // be decoded safely. Refuse it here instead of dispatching GEN and
127	        // failing later inside the backend. Other backends do not expose this
128	        // TRT-LLM-specific field and are unaffected.
129	        let ctx_request_id = disaggregated_params.get("ctx_request_id");
130	        let is_trtllm_context_handoff = disaggregated_params
131	            .get("request_type")
132	            .and_then(serde_json::Value::as_str)
133	            == Some("context_only");
134	        if ctx_request_id.is_some_and(serde_json::Value::is_null)
135	            || (is_trtllm_context_handoff && ctx_request_id.is_none())
136	        {
137	            return Err(PrefillError::NoDisaggregatedParams(
138	                "Prefill router output has no usable ctx_request_id for a non-terminal handoff"
139	                    .to_string(),
140	            ));
141	        }
142	
143	        Ok(PrefillCompletion::Handoff {
144	            result: crate::protocols::common::preprocessor::PrefillResult {
145	                disaggregated_params,
146	                prompt_tokens_details,
147	            },
148	            worker_link: output.worker_trace_link.clone(),
149	        })
150	    }
151	
152	    pub(super) fn spawn_prefill_task(
153	        &self,
154	        prefill_stream: ManyOut<Annotated<LLMEngineOutput>>,
155	        tracker: Option<Arc<RequestTracker>>,
156	        phase_transition_permit: OwnedSemaphorePermit,
157	    ) {
158	        let span = tracing::Span::current();
159	        let task_guard = self.task_guard.clone();
160	        tokio::spawn(
161	            async move {
162	                drop(phase_transition_permit);
163	                match Self::consume_prefill_stream(prefill_stream, tracker, task_guard).await {
164	                    Ok(_) => tracing::debug!("Prefill background task completed"),
165	                    Err(error) => tracing::warn!("Prefill background task error: {error:?}"),
166	                }
167	            }
168	            .instrument(span),
169	        );
170	    }
171	}
