268	#[async_trait]
269	impl<Sel>
270	    Operator<
271	        SingleIn<PreprocessedRequest>,
272	        ManyOut<Annotated<LLMEngineOutput>>,
273	        SingleIn<PreprocessedRequest>,
274	        ManyOut<Annotated<LLMEngineOutput>>,
275	    > for PrefillRouter<Sel>
276	where
277	    Sel: WorkerSelector<ModelRuntimeConfig> + Send + 'static,
278	{
279	    async fn generate(
280	        &self,
281	        request: SingleIn<PreprocessedRequest>,
282	        next: ServerStreamingEngine<PreprocessedRequest, Annotated<LLMEngineOutput>>,
283	    ) -> Result<ManyOut<Annotated<LLMEngineOutput>>> {
284	        // Extract request data while preserving context
285	        let (mut req, context) = request.into_parts();
286	        let request_id = context.id().to_string();
287	        let metadata = context.metadata().clone();
288	        let policy_class = context.metadata().get("policy-class").cloned();
289	        let engine_ctx = context.context();
290	
291	        // Conditional-disagg bypass is a router-owned decision. Drop any
292	        // client-supplied marker before the policy runs so normal disagg
293	        // requests cannot accidentally or maliciously skip remote prefill.
294	        req.annotations
295	            .retain(|annotation| annotation != BYPASS_REMOTE_PREFILL_ANNOTATION);
296	
297	        // Save original max_tokens for decode
298	        let original_max_tokens = req.stop_conditions.max_tokens;
299	
300	        // If the prefill router is not activated (no prefill workers discovered) or has been
301	        // deactivated (all prefill workers died), route directly to the backend. Model admission
302	        // remains gated by the registered worker topology before the request reaches this stage.
303	        if self.lifecycle_state() != PrefillLifecycleState::Active {
304	            return next.generate(context.map(|_| req)).await;
305	        }
306	
307	        let session_affinity = context
308	            .get_optional::<SessionAffinityId>(SESSION_AFFINITY_CONTEXT_KEY)
309	            .map_err(|message| anyhow::anyhow!("invalid session affinity context: {message}"))?;
310	
311	        let decode_affinity_target =
312	            self.decode_session_affinity_target(session_affinity.as_deref())?;
313	
314	        if self.conditional_disagg_policy.is_enabled() {
315	            match self
316	                .select_decode_worker_for_conditional_disagg(
317	                    &req,
318	                    &request_id,
319	                    policy_class.clone(),
320	                    session_affinity.as_deref(),
321	                    decode_affinity_target,
322	                )
323	                .await
324	            {
325	                Ok(Some(decision)) => {
326	                    tracing::info!(
327	                        request_id = %request_id,
328	                        worker_id = decision.worker.worker_id,
329	                        dp_rank = decision.worker.dp_rank,
330	                        net_new_tokens = decision.net_new_tokens,
331	                        overlap_tokens = decision.overlap_tokens,
332	                        "Conditional disagg routing to decode worker"
333	                    );
334	
335	                    if req.tracker.is_none() {
336	                        req.tracker = Some(Arc::new(RequestTracker::new()));
337	                    }
338	                    if let Some(ref tracker) = req.tracker {
339	                        let _decode_permit = tracker.set_phase(RequestPhase::Decode).await;
340	                    }
341	
342	                    let routing = req.routing_mut();
343	                    routing.decode_worker_id = Some(decision.worker.worker_id);
344	                    routing.dp_rank = Some(decision.worker.dp_rank);
345	
346	                    req.annotations
347	                        .push(BYPASS_REMOTE_PREFILL_ANNOTATION.to_string());
348	
349	                    // TODO: This advisory selection does not reserve decode capacity. If the
350	                    // exact pinned admission below races and fails, the no-clone fix is a
351	                    // scheduler reservation handoff rather than retrying with a mutated request.
352	                    let response_stream = next.generate(context.map(|_| req)).await?;
353	                    let ctx = response_stream.context();
354	                    let annotation = Annotated::<LLMEngineOutput>::from_annotation(
355	                        BYPASS_REMOTE_PREFILL_ANNOTATION,
356	                        &true,
357	                    )?;
358	                    let merged = stream::once(async move { annotation }).chain(response_stream);
359	                    return Ok(ResponseStream::new(Box::pin(merged), ctx));
360	                }
361	                Ok(None) => {}
362	                Err(error) => {
363	                    tracing::warn!(
364	                        request_id = %request_id,
365	                        error = %error,
366	                        "Conditional disagg decision failed; falling back to remote prefill"
367	                    );
368	                }
369	            }
370	        }
371	
372	        // Ensure tracker exists for routing decisions in disaggregated mode.
373	        // Create one if not provided by the upstream DeltaGenerator.
374	        if req.tracker.is_none() {
375	            req.tracker = Some(Arc::new(RequestTracker::new()));
376	        }
377	        let tracker = req.tracker.as_ref().unwrap();
378	        let prefill_phase_barrier = tracker.set_phase(RequestPhase::Prefill).await;
379	
380	        // Prepare prefill request with max_tokens = 1 (clone after tracker is set)
381	        let mut prefill_req = req.clone();
382	        prefill_req.stop_conditions.max_tokens = Some(1);
383	
384	        // Try to resolve prefill worker upfront: if we can get bootstrap info early,
385	        // spawn prefill in background and proceed to decode immediately.
386	        let preselected_worker = prefill_req
387	            .routing
388	            .as_ref()
389	            .and_then(|r| r.prefill_worker_id);
390	
391	        let tracker = prefill_req.tracker.clone();
392	        let mut prefill_context =
393	            Context::with_id_and_metadata(prefill_req, request_id.clone(), metadata.clone());
394	        propagate_first_response_guard(&context, &mut prefill_context)?;
395	        if let Some(session_affinity) = session_affinity {
396	            prefill_context.insert(
397	                SESSION_AFFINITY_CONTEXT_KEY,
398	                session_affinity.as_ref().clone(),
399	            );
400	        }
401	        let Some(binding) = self.binding.load_full() else {
402	            return next.generate(context.map(|_| req)).await;
403	        };
404	
405	        // Keyed on the prefill mode, not the decode set's, and checked after
406	        // the binding loads because that is where the prefill mode lives.
407	        if binding.prefill_router_mode.is_direct_routing() && preselected_worker.is_none() {
408	            return Err(anyhow::anyhow!(
409	                "Prefill worker ID required in Direct routing mode but none found in request. \
410	                 Expected prefill_worker_id to be set via x-dynamo-prefill-instance-id header by external router (e.g., EPP)."
411	            ));
412	        }
413	
414	        let router = &binding.router;
415	        let endpoint_id = &binding.endpoint_id;
416	        let prefill_result: Result<(PrefillOutcome, Option<RoutingConstraints>)> = async {
417	            let (prepared, prefill_stream) = router
418	                .select_and_dispatch_prefill(prefill_context, |request, target| {
419	                    self.prepare_prefill_dispatch(request, target, endpoint_id)
420	                })
421	                .await?;
422	            let topology_constraints = prepared.topology_constraints;
423	            let outcome = if let Some(bootstrap_info) = prepared.bootstrap_info {
424	                self.spawn_prefill_task(prefill_stream, tracker, prefill_phase_barrier);
425	                PrefillOutcome::Bootstrap {
426	                    bootstrap_info,
427	                    worker_id: prepared.worker_id,
428	                }
429	            } else {
430	                drop(prefill_phase_barrier);
431	                let completion =
432	                    Self::consume_prefill_stream(prefill_stream, tracker, self.task_guard.clone())
433	                        .await?;
434	
435	                match completion {
436	                    PrefillCompletion::Handoff {
437	                        result,
438	                        worker_link,
439	                    } => {
440	                        if let Some(bootstrap_info) =
441	                            extract_bootstrap_info(&result.disaggregated_params)
442	                        {
443	                            PrefillOutcome::Bootstrap {
444	                                bootstrap_info,
445	                                worker_id: prepared.worker_id,
446	                            }
447	                        } else {
448	                            PrefillOutcome::Completed {
449	                                result,
450	                                worker_id: prepared.worker_id,
451	                                worker_link,
452	                            }
453	                        }
454	                    }
455	                    PrefillCompletion::Terminal { output } => PrefillOutcome::Terminal { output },
456	                }
457	            };
458	            Ok((outcome, topology_constraints))
459	        }
460	        .await;
461	        let (outcome, topology_constraints) = match prefill_result {
462	            Ok(result) => result,
463	            Err(error) => {
464	                use dynamo_runtime::error::{ErrorType, match_error_chain};
465	                if match_error_chain(
466	                    error.as_ref(),
467	                    &[ErrorType::ResourceExhausted, ErrorType::WorkerOverloaded],
468	                    &[],
469	                ) {
470	                    tracing::warn!(
471	                        error = %error,
472	                        "request rejected by prefill worker (at capacity)"
473	                    );
474	                } else {
475	                    tracing::error!(error = %error, "Remote prefill failed, failing request");
476	                }
477	                return Err(error);
478	            }
479	        };
480	
481	        // A prefill request can terminate before the backend establishes a KV
482	        // handoff (for example, EOS on the one-token context step). Native
483	        // disaggregated backends return that context response directly instead
484	        // of launching a generation-only request with missing handoff IDs.
485	        let outcome = match outcome {
486	            PrefillOutcome::Terminal { output } => {
487	                let output = strip_terminal_disaggregated_params(*output);
488	                return Ok(dynamo_runtime::pipeline::ResponseStream::new(
489	                    Box::pin(stream::once(async move { output })),
490	                    engine_ctx,
491	                ));
492	            }
493	            outcome => outcome,
494	        };
495	
496	        // NVBugs 5969206: Do NOT abort decode routing when context is killed.
497	        // In disaggregated serving, the prefill may have completed and KV transfer
498	        // is in flight. Blocking decode here orphans the transfer (no receiver)
499	        // and leaks KV blocks permanently. The decode handler's
500	        // kv_transfer_complete_event guard will clean up after KV is received.
501	        // Log-only; decode routing must proceed for KV transfer cleanup.
502	        if engine_ctx.is_stopped() || engine_ctx.is_killed() {
503	            tracing::debug!(
504	                "Context {} killed/stopped after prefill, allowing decode routing for KV transfer",
505	                engine_ctx.id()
506	            );
507	        }
508	
509	        tracing::debug!("Prefill completed, proceeding to decode");
510	
511	        // Set phase to Decode for the decode request.
512	        // In bootstrap path, this blocks until the spawned prefill task releases its
513	        // phase barrier after routing completes, ensuring correct worker attribution.
514	        if let Some(ref tracker) = req.tracker {
515	            let _decode_permit = tracker.set_phase(RequestPhase::Decode).await;
516	        }
517	
518	        let mut decode_req = req;
519	        match outcome {
520	            PrefillOutcome::Bootstrap {
521	                bootstrap_info,
522	                worker_id,
523	            } => {
524	                decode_req.bootstrap_info = Some(bootstrap_info);
525	                decode_req.routing_mut().prefill_worker_id = Some(worker_id);
526	            }
527	            PrefillOutcome::Completed {
528	                result,
529	                worker_id,
530	                worker_link,
531	            } => {
532	                decode_req.prefill_result = Some(result);
533	                decode_req.migration_link = worker_link;
534	                decode_req.routing_mut().prefill_worker_id = Some(worker_id);
535	            }
536	            PrefillOutcome::Terminal { .. } => {
537	                unreachable!("terminal prefill outcomes return before decode routing")
538	            }
539	        };
540	
541	        if let Some(topology_constraints) = topology_constraints {
542	            merge_decode_topology_constraints(&mut decode_req, topology_constraints);
543	        }
544	
545	        decode_req.stop_conditions.max_tokens = original_max_tokens;
546	
547	        // Decode should not account prompt-side load. Normal disagg also
548	        // forces zero overlap credit so decode routing stays load-only.
549	        let existing_override = decode_req.router_config_override.take();
550	        decode_req.router_config_override = Some(build_decode_router_override(
551	            existing_override,
552	            self.conditional_disagg_policy.is_enabled(),
553	        ));
554	
555	        next.generate(context.map(|_| decode_req)).await
556	    }
557	}
