559	impl<Sel> PrefillRouter<Sel>
560	where
561	    Sel: WorkerSelector<ModelRuntimeConfig> + Send + 'static,
562	{
563	    pub(crate) fn conditional_disagg_enabled(&self) -> bool {
564	        self.conditional_disagg_policy.is_enabled()
565	    }
