567	    pub(crate) fn set_decode_session_affinity(&self, affinity: Option<AffinityCoordinator>) {
568	        let Some(affinity) = affinity else {
569	            return;
570	        };
571	        if self.decode_session_affinity.get().is_some() {
572	            return;
573	        }
574	        let _ = self.decode_session_affinity.set(affinity);
575	    }
576	
577	    fn decode_session_affinity_target(
578	        &self,
579	        session_affinity: Option<&SessionAffinityId>,
580	    ) -> Result<Option<AffinityTarget>> {
581	        let Some(session_affinity) = session_affinity else {
582	            return Ok(None);
583	        };
584	        let Some(affinity) = self.decode_session_affinity.get() else {
585	            return Ok(None);
586	        };
587	        affinity.query_target(session_affinity, None)
588	    }
