590	    fn prepare_prefill_dispatch(
591	        &self,
592	        request: &mut PreprocessedRequest,
593	        target: AffinityTarget,
594	        endpoint_id: &EndpointId,
595	    ) -> anyhow::Result<PreparedPrefill> {
596	        let AffinityTarget { worker_id, dp_rank } = target;
597	        let topology_constraints =
598	            self.preflight_kv_transfer_constraints(Some(endpoint_id), worker_id)?;
599	
600	        let bootstrap_info = self
601	            .model_manager
602	            .get_disaggregated_endpoint(endpoint_id, worker_id)
603	            .map(|endpoint| (endpoint_id, endpoint))
604	            .and_then(|(endpoint_id, endpoint)| {
605	                let host = endpoint.bootstrap_host?;
606	                let port = endpoint.bootstrap_port?;
607	                let dp_size = self
608	                    .model_manager
609	                    .get_data_parallel_size(endpoint_id, worker_id);
610	                let random_room = rand::random_range(0..=i64::MAX.cast_unsigned());
611	                let bootstrap_room = compute_bootstrap_room(dp_rank, dp_size, random_room);
612	                Some(BootstrapInfo {
613	                    bootstrap_host: host,
614	                    bootstrap_port: port,
615	                    bootstrap_room,
616	                    handoff_id: Some(Uuid::new_v4()),
617	                })
618	            });
619	        let routing = request.routing_mut();
620	        routing.prefill_worker_id = Some(worker_id);
621	        routing.prefill_dp_rank = dp_rank;
622	        request.bootstrap_info = bootstrap_info.clone();
623	
624	        Ok(PreparedPrefill {
625	            worker_id,
626	            bootstrap_info,
627	            topology_constraints,
628	        })
629	    }
630	
631	    fn preflight_kv_transfer_constraints(
632	        &self,
633	        endpoint_id: Option<&EndpointId>,
634	        worker_id: u64,
635	    ) -> anyhow::Result<Option<RoutingConstraints>> {
636	        let Some(endpoint_id) = endpoint_id else {
637	            return Ok(None);
638	        };
639	
640	        self.model_manager
641	            .get_kv_transfer_routing_constraints(endpoint_id, worker_id)
642	    }
643	}
