645	fn compute_bootstrap_room(dp_rank: Option<u32>, dp_size: Option<u32>, random_room: u64) -> u64 {
646	    let max_room = i64::MAX.cast_unsigned();
647	    debug_assert!(random_room <= max_room);
648	    match (dp_rank, dp_size) {
649	        (Some(rank), Some(size)) if size > 0 => {
650	            let size = size as u64;
651	            let rank = rank as u64;
652	            let max_quotient = (max_room - rank) / size;
653	            let quotient = random_room % (max_quotient + 1);
654	            quotient * size + rank
655	        }
656	        _ => random_room,
657	    }
658	}
659	
660	fn build_decode_router_override(
661	    existing_override: Option<RouterConfigOverride>,
662	    allow_decode_overlap_affinity: bool,
663	) -> RouterConfigOverride {
664	    let mut override_config = existing_override.unwrap_or_default();
665	
666	    // Normal disagg keeps decode routing load-only by forcing zero overlap
667	    // credit. Conditional disagg leaves this unset so the base router
668	    // `overlap_score_credit` applies, unless the request already had an
669	    // explicit override.
670	    if !allow_decode_overlap_affinity {
671	        override_config.overlap_score_credit = Some(0.0);
672	    }
673	    override_config.assume_kv_reuse = Some(false);
674	    override_config.track_prefill_tokens = Some(false);
675	
676	    override_config
677	}
