679	fn merge_decode_topology_constraints(
680	    request: &mut PreprocessedRequest,
681	    topology_constraints: RoutingConstraints,
682	) {
683	    if topology_constraints.is_empty() {
684	        return;
685	    }
686	
687	    let routing_constraints = request
688	        .routing_mut()
689	        .routing_constraints
690	        .get_or_insert_with(RoutingConstraints::default);
691	    routing_constraints
692	        .required_taints
693	        .extend(topology_constraints.required_taints);
694	    routing_constraints
695	        .preferred_taints
696	        .extend(topology_constraints.preferred_taints);
697	}
