4	//! Conditional-disagg bypass policy.
5	//!
6	//! Decides whether a request should skip remote prefill and run prefill
7	//! locally on the chosen decode worker. The trait operates over summary
8	//! signals so future policies can plug in without changing the router call site.
9	
10	use async_trait::async_trait;
11	
12	use crate::config::{ConditionalDisaggPolicyKind, KvRouterConfig};
13	
14	/// Default effective-ISL absolute threshold (tokens). A request bypasses to
15	/// AGG only if its net-new prefill stays under this cap.
16	pub const DEFAULT_CONDITIONAL_DISAGG_EFF_ISL_THRESHOLD: usize = 2048;
17	
18	/// Default effective-ISL ratio threshold. A request bypasses to AGG only if
19	/// `eff_isl / prompt_tokens` stays under this fraction.
20	pub const DEFAULT_CONDITIONAL_DISAGG_EFF_ISL_RATIO_THRESHOLD: f64 = 0.7;
21	
22	/// Inputs passed to a `ConditionalDisaggPolicy` when deciding whether to
23	/// bypass remote prefill.
24	#[derive(Debug, Clone, Copy, PartialEq)]
25	#[non_exhaustive]
26	pub struct ConditionalDisaggDecisionInput {
27	    /// Total prompt token count.
28	    pub prompt_tokens: usize,
29	
30	    /// Effective cache credit on the chosen decode worker, in weighted tokens.
31	    pub decode_chosen_cached_tokens: usize,
32	
33	    /// Whether the prefill worker the router would pick for this request is
34	    /// over the prefill-busy line. `None` means the signal is unavailable.
35	    pub prefill_chosen_worker_busy: Option<bool>,
36	
37	    /// Whether the decode worker the router would pick for this request is
38	    /// over the decode-busy line. `None` means the gate is disabled or the
39	    /// signal is unavailable.
40	    pub decode_chosen_worker_busy: Option<bool>,
41	}
42	
43	impl ConditionalDisaggDecisionInput {
44	    pub fn new(prompt_tokens: usize, decode_chosen_cached_tokens: usize) -> Self {
45	        Self {
46	            prompt_tokens,
47	            decode_chosen_cached_tokens,
48	            prefill_chosen_worker_busy: None,
49	            decode_chosen_worker_busy: None,
50	        }
51	    }
52	
53	    pub fn with_prefill_chosen_worker_busy(mut self, busy: Option<bool>) -> Self {
54	        self.prefill_chosen_worker_busy = busy;
55	        self
56	    }
57	
58	    pub fn with_decode_chosen_worker_busy(mut self, busy: Option<bool>) -> Self {
59	        self.decode_chosen_worker_busy = busy;
60	        self
61	    }
62	
63	    /// Effective net-new prefill in tokens after the decode-side weighted
64	    /// cache hit is subtracted.
65	    pub fn net_new_tokens(self) -> usize {
66	        self.prompt_tokens
67	            .saturating_sub(self.decode_chosen_cached_tokens.min(self.prompt_tokens))
68	    }
69	}
70	
71	#[async_trait]
72	pub trait ConditionalDisaggPolicy: Send + Sync {
73	    fn is_enabled(&self) -> bool;
74	
75	    /// Decide whether the request should skip remote prefill.
76	    async fn should_bypass_remote_prefill(&self, input: ConditionalDisaggDecisionInput) -> bool;
77	
78	    /// True iff this policy consumes
79	    /// [`ConditionalDisaggDecisionInput::prefill_chosen_worker_busy`].
80	    fn needs_prefill_worker_busy(&self) -> bool {
81	        false
82	    }
83	}
84	
85	/// Build the configured conditional-disagg policy. Returns a disabled policy
86	/// when conditional disagg is not enabled.
87	pub fn make_conditional_disagg_policy(
88	    config: Option<&KvRouterConfig>,
89	) -> Box<dyn ConditionalDisaggPolicy> {
90	    let Some(config) = config else {
91	        return Box::new(IslBoundingPolicy::disabled());
92	    };
93	    match config.conditional_disagg_policy {
94	        ConditionalDisaggPolicyKind::IslBounding => {
95	            Box::new(IslBoundingPolicy::from_config(config))
96	        }
97	        ConditionalDisaggPolicyKind::PrefillLoad => {
98	            Box::new(PrefillLoadPolicy::from_config(config))
99	        }
100	        ConditionalDisaggPolicyKind::IslOrLoad => Box::new(IslOrLoadPolicy::from_config(config)),
101	    }
102	}
103	
104	pub fn policy_needs_prefill_worker_busy(config: Option<&KvRouterConfig>) -> bool {
105	    make_conditional_disagg_policy(config).needs_prefill_worker_busy()
106	}
107	
108	/// v1 conditional-disagg policy. Bypasses to AGG when the request is both
109	/// small in absolute net-new prefill and mostly cached on the decode worker.
110	#[derive(Debug, Clone, Copy, PartialEq)]
111	pub struct IslBoundingPolicy {
112	    enabled: bool,
113	    eff_isl_threshold: usize,
114	    eff_isl_ratio_threshold: f64,
115	}
116	
117	impl IslBoundingPolicy {
118	    pub fn new(enabled: bool, eff_isl_threshold: usize, eff_isl_ratio_threshold: f64) -> Self {
119	        Self {
120	            enabled,
121	            eff_isl_threshold,
122	            eff_isl_ratio_threshold,
123	        }
124	    }
125	
126	    pub fn from_config(config: &KvRouterConfig) -> Self {
127	        Self {
128	            enabled: config.conditional_disagg_enabled,
129	            eff_isl_threshold: config.conditional_disagg_eff_isl_threshold,
130	            eff_isl_ratio_threshold: config.conditional_disagg_eff_isl_ratio_threshold,
131	        }
132	    }
133	
134	    pub fn disabled() -> Self {
135	        Self {
136	            enabled: false,
137	            eff_isl_threshold: DEFAULT_CONDITIONAL_DISAGG_EFF_ISL_THRESHOLD,
138	            eff_isl_ratio_threshold: DEFAULT_CONDITIONAL_DISAGG_EFF_ISL_RATIO_THRESHOLD,
139	        }
140	    }
141	}
142	
143	impl Default for IslBoundingPolicy {
144	    fn default() -> Self {
145	        Self::disabled()
146	    }
147	}
148	
149	#[async_trait]
150	impl ConditionalDisaggPolicy for IslBoundingPolicy {
151	    fn is_enabled(&self) -> bool {
152	        self.enabled
153	    }
154	
155	    async fn should_bypass_remote_prefill(&self, input: ConditionalDisaggDecisionInput) -> bool {
156	        if !self.enabled {
157	            return false;
158	        }
159	        let eff_isl = input.net_new_tokens();
160	        if eff_isl >= self.eff_isl_threshold {
161	            return false;
162	        }
163	        let denom = input.prompt_tokens.max(1) as f64;
164	        let ratio = eff_isl as f64 / denom;
165	        ratio < self.eff_isl_ratio_threshold
166	    }
167	}
