169	/// v1.5 conditional-disagg policy. Bypasses to AGG when the prefill worker
170	/// the router would pick for this request is already over the prefill-busy line.
171	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
172	pub struct PrefillLoadPolicy {
