236	    pub fn disabled() -> Self {
237	        Self {
238	            isl: IslBoundingPolicy::disabled(),
239	            load: PrefillLoadPolicy::disabled(),
240	        }
241	    }
242	}
243	
244	impl Default for IslOrLoadPolicy {
245	    fn default() -> Self {
246	        Self::disabled()
247	    }
248	}
