229	            tracing::debug!(
230	                request_id,
231	                prefill_chosen_worker_busy = ?busy,
232	                "Conditional disagg prefill-load condition inspected selected prefill worker"
233	            );
234	            input = input.with_prefill_chosen_worker_busy(busy);
235	        }
236	        let net_new_tokens = input.net_new_tokens();
237	        let overlap_tokens = (overlap_blocks as usize) * block_size;
238	
239	        let policy_says_bypass = self
240	            .conditional_disagg_policy
241	            .should_bypass_remote_prefill(input)
242	            .await;
